 "content": "from collections import deque


def transform(grid):
    """Erase the nonzero 4-connected object containing the fewest 9 cells."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            nines = 0
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                nines += grid[y][x] == 9
                for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            components.append((nines, cells))
    if components:
        least = min(count for count, _ in components)
        for count, cells in components:
            if count == least:
                for r, c in cells:
                    out[r][c] = 0
    return out


